const SAAS_SCHEMA=["CREATE TABLE IF NOT EXISTS saas_workspaces(id TEXT PRIMARY KEY,team_name TEXT NOT NULL,contact TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 0);", "CREATE TABLE IF NOT EXISTS saas_bank(id INTEGER PRIMARY KEY CHECK(id=1),bank TEXT NOT NULL,account TEXT NOT NULL,holder TEXT NOT NULL,contact TEXT NOT NULL,qr_data TEXT NOT NULL DEFAULT '');", "CREATE TABLE IF NOT EXISTS saas_orders(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,plan TEXT NOT NULL CHECK(plan IN ('month','year')),amount INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','claimed','approved','rejected')),reference TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL,reviewed_at INTEGER,grant_until INTEGER,reviewed_by TEXT);", "CREATE INDEX IF NOT EXISTS saas_orders_workspace ON saas_orders(workspace_id,created_at);", "CREATE TABLE IF NOT EXISTS saas_payment_history_deleted(order_id TEXT PRIMARY KEY,deleted_at INTEGER NOT NULL,deleted_by TEXT NOT NULL);", "CREATE TABLE IF NOT EXISTS saas_access_grants(order_id TEXT PRIMARY KEY,starts_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,plan TEXT NOT NULL);", "INSERT OR IGNORE INTO saas_access_grants(order_id,starts_at,expires_at,plan) SELECT id,reviewed_at,grant_until,plan FROM saas_orders WHERE status='approved' AND reviewed_at IS NOT NULL AND grant_until IS NOT NULL;", "CREATE TABLE IF NOT EXISTS saas_order_revocations(order_id TEXT PRIMARY KEY,revoked_at INTEGER NOT NULL,revoked_by TEXT NOT NULL,previous_expiry INTEGER NOT NULL,new_expiry INTEGER NOT NULL);", "CREATE TABLE IF NOT EXISTS saas_signup_attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,until INTEGER NOT NULL);", "CREATE TABLE IF NOT EXISTS saas_owner_sessions(token_hash TEXT PRIMARY KEY,csrf TEXT NOT NULL,expires INTEGER NOT NULL,key_hash TEXT NOT NULL);", "CREATE TABLE IF NOT EXISTS saas_credentials(workspace_id TEXT NOT NULL,role TEXT NOT NULL,salt TEXT NOT NULL,password_hash TEXT NOT NULL,PRIMARY KEY(workspace_id,role));", "CREATE TABLE IF NOT EXISTS saas_sessions(workspace_id TEXT NOT NULL,token_hash TEXT NOT NULL,role TEXT NOT NULL,csrf TEXT NOT NULL,expires INTEGER NOT NULL,PRIMARY KEY(workspace_id,token_hash));", "CREATE TABLE IF NOT EXISTS saas_attempts(workspace_id TEXT NOT NULL,key TEXT NOT NULL,count INTEGER NOT NULL,until INTEGER NOT NULL,PRIMARY KEY(workspace_id,key));", "CREATE TABLE IF NOT EXISTS saas_schedule(workspace_id TEXT NOT NULL,id INTEGER NOT NULL CHECK(id=1),revision INTEGER NOT NULL,data TEXT NOT NULL,updated_at TEXT NOT NULL,action TEXT NOT NULL,PRIMARY KEY(workspace_id,id));", "CREATE TABLE IF NOT EXISTS saas_history(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id TEXT NOT NULL,revision INTEGER NOT NULL,data TEXT NOT NULL,action TEXT NOT NULL,updated_at TEXT NOT NULL);", "CREATE INDEX IF NOT EXISTS saas_sessions_expiry ON saas_sessions(workspace_id,expires);", "CREATE TRIGGER IF NOT EXISTS saas_schedule_history AFTER UPDATE ON saas_schedule BEGIN\n INSERT INTO saas_history(workspace_id,revision,data,action,updated_at) VALUES(new.workspace_id,new.revision,new.data,new.action,new.updated_at);\n DELETE FROM saas_history WHERE workspace_id=new.workspace_id AND id NOT IN (SELECT id FROM saas_history WHERE workspace_id=new.workspace_id ORDER BY id DESC LIMIT 30);\nEND;", "DROP TRIGGER IF EXISTS saas_order_approved;", "CREATE TRIGGER saas_order_approved AFTER UPDATE ON saas_orders WHEN new.status='approved' AND old.status IN ('pending','claimed') BEGIN\n INSERT OR IGNORE INTO saas_access_grants(order_id,starts_at,expires_at,plan) VALUES(new.id,new.reviewed_at,new.grant_until,new.plan);\n UPDATE saas_workspaces SET expires_at=MAX(expires_at,new.grant_until),version=version+1 WHERE id=new.workspace_id;\nEND;", "CREATE TRIGGER IF NOT EXISTS saas_order_revoked AFTER UPDATE ON saas_orders WHEN old.status='approved' AND new.status='rejected' BEGIN\n UPDATE saas_workspaces SET expires_at=(SELECT new_expiry FROM saas_order_revocations WHERE order_id=new.id),version=version+1 WHERE id=new.workspace_id AND EXISTS(SELECT 1 FROM saas_order_revocations WHERE order_id=new.id);\nEND;"];
