function saasMonthEnd(base,months){const local=new Date(base+7*3600000),day=local.getUTCDate();local.setUTCDate(1);local.setUTCMonth(local.getUTCMonth()+months);const last=new Date(Date.UTC(local.getUTCFullYear(),local.getUTCMonth()+1,0)).getUTCDate();local.setUTCDate(Math.min(day,last));return local.getTime()-7*3600000;}
